(()=>{
'use strict';
const STORE='kage-auth-session-v1',prefs='kage-local-preferences';
const photoAvatars={"photo1":"data:image/jpeg;base64,","photo2":"data:image/jpeg;base64,","photo3":"data:image/jpeg;base64,","photo4":"data:image/jpeg;base64,","photo5":"data:image/jpeg;base64,","photo6":"data:image/jpeg;base64,","photo7":"data:image/jpeg;base64,","photo8":"data:image/jpeg;base64,","photo9":"data:image/jpeg;base64,"};

let config=null,session=null,profile={display_name:'',avatar:'photo1',accent:'rose'}, selectedAvatar='photo1',dialog=null,activeTab='account';
function avatar(id){return photoAvatars[id]||photoAvatars.photo1}
function loadSession(){try{return JSON.parse(localStorage.getItem(STORE)||'null')}catch(e){return null}}function saveSession(s){session=s;try{if(s)localStorage.setItem(STORE,JSON.stringify(s));else localStorage.removeItem(STORE)}catch(e){}}
function applyAccent(a){document.body.classList.remove('kg-accent-blue','kg-accent-purple');if(a==='blue'||a==='purple')document.body.classList.add('kg-accent-'+a);try{localStorage.setItem(prefs,a)}catch(e){}}
function headers(token){return {'apikey':config.key,'Authorization':'Bearer '+(token||config.key),'Content-Type':'application/json'}}
async function call(path,{method='GET',body,token,prefer}={}){let h=headers(token);if(prefer)h.Prefer=prefer;let r=await fetch(config.url+path,{method,headers:h,...(body!==undefined?{body:JSON.stringify(body)}:{})});let text=await r.text(),data=null;try{data=text?JSON.parse(text):null}catch(e){}if(!r.ok)throw Error(data?.msg||data?.error_description||data?.message||data?.error||'Request failed. Please try again.');return data}
async function refresh(){if(!session?.refresh_token)return false;try{let d=await call('/auth/v1/token?grant_type=refresh_token',{method:'POST',body:{refresh_token:session.refresh_token}});d.expires_at=Math.floor(Date.now()/1000)+(d.expires_in||3600);saveSession(d);return true}catch(e){saveSession(null);return false}}
async function token(){if(!session?.access_token)return null;if(session.expires_at&&session.expires_at<Math.floor(Date.now()/1000)+60){if(!await refresh())return null}return session.access_token}
async function fetchProfile(){let t=await token();if(!t||!session?.user?.id)return;try{let d=await call('/rest/v1/kage_profiles?id=eq.'+encodeURIComponent(session.user.id)+'&select=id,display_name,avatar,accent',{token:t});if(d?.[0])profile={...profile,...d[0]};applyAccent(profile.accent)}catch(e){console.warn('Profile not available:',e.message)}}
function setMessage(text){let m=dialog?.querySelector('.kg-message');if(m)m.textContent=text||''}
function element(tag,cls,text){let x=document.createElement(tag);if(cls)x.className=cls;if(text!==undefined)x.textContent=text;return x}
function updateButton(){document.querySelectorAll('.kg-account-button').forEach(b=>{b.querySelector('img').src=avatar(profile.avatar);b.querySelector('span').textContent=session?.user?(profile.display_name||'My account'):'Sign in'})}
function close(){dialog?.remove();dialog=null}
function open(tab='account'){close();activeTab=tab;let overlay=element('div','kg-overlay');overlay.onclick=e=>{if(e.target===overlay)close()};dialog=overlay;document.body.append(overlay);draw()}
function draw(){if(!dialog)return;dialog.textContent='';let box=element('div','kg-dialog'),top=element('div','kg-top'),h=element('h2','',session?.user?'Your KageAnime':'Welcome to KageAnime'),x=element('button','kg-close','×');x.type='button';x.setAttribute('aria-label','Close');x.onclick=close;top.append(h,x);box.append(top);dialog.append(box);
if(!config?.configured){let m=element('p','kg-alert','Real accounts are not configured yet. The website owner needs to connect Supabase and set the required server environment variables.');box.append(m);return}
let tabs=element('div','kg-tabs');for(let [id,label] of (session?.user?[['account','Profile'],['history','Watch history'],['settings','Settings']]:[['account','Sign in'],['signup','Create account']])){let b=element('button','kg-tab'+(activeTab===id?' active':''),label);b.type='button';b.onclick=()=>{activeTab=id;draw()};tabs.append(b)}box.append(tabs);
if(!session?.user){drawAuth(box,activeTab==='signup');return}if(activeTab==='history'){drawHistory(box);return}if(activeTab==='settings'){drawSettings(box);return}drawProfile(box)}
function field(label,type,id,placeholder){let wrap=element('label','kg-field',label),input=element('input');input.type=type;input.id=id;input.placeholder=placeholder;input.required=true;if(type==='password')input.minLength=8;wrap.append(input);return wrap}
function drawAuth(box,signup){let form=element('form');form.append(field('Email','email','kg-email','you@example.com'),field('Password','password','kg-password','At least 8 characters'));let note=element('p','kg-note',signup?'Use your own email. You may need to confirm it before signing in.':'Sign in to sync your profile and watch history across devices.');let message=element('p','kg-message'),button=element('button','kg-primary',signup?'Create account':'Sign in');button.type='submit';form.append(note,message,button);box.append(form);form.onsubmit=async e=>{e.preventDefault();let email=form.querySelector('#kg-email').value.trim(),password=form.querySelector('#kg-password').value;button.disabled=true;setMessage('Please wait...');try{let d=await call(signup?'/auth/v1/signup':'/auth/v1/token?grant_type=password',{method:'POST',body:{email,password}});if(d?.access_token){d.expires_at=Math.floor(Date.now()/1000)+(d.expires_in||3600);saveSession(d);await fetchProfile();updateButton();activeTab='account';draw()}else setMessage('Account created. Check your email to confirm, then sign in.')}catch(err){setMessage(err.message)}finally{button.disabled=false}}}
function drawProfile(box){let info=element('p','kg-note','Signed in as '+(session.user.email||'your account')),display=field('Display name','text','kg-name','Your display name');display.querySelector('input').required=false;display.querySelector('input').value=profile.display_name||'';let avatarLabel=element('p','kg-note','Choose your profile picture'),choices=element('div','kg-avatars');selectedAvatar=(photoAvatars[profile.avatar]?profile.avatar:'photo1');function avatars(){choices.textContent='';Object.keys(photoAvatars).forEach(id=>{let b=element('button','kg-avatar-option'+(selectedAvatar===id?' selected':''));b.type='button';b.title='Profile picture '+id.replace('photo','');b.setAttribute('aria-label','Choose '+b.title);let img=element('img');img.src=avatar(id);img.alt='';b.append(img);b.onclick=()=>{selectedAvatar=id;avatars()};choices.append(b)})}avatars();let message=element('p','kg-message'),actions=element('div','kg-actions'),save=element('button','kg-primary','Save profile'),logout=element('button','kg-secondary','Sign out');save.type=logout.type='button';actions.append(save,logout);box.append(info,display,avatarLabel,choices,message,actions);save.onclick=async()=>{save.disabled=true;setMessage('Saving...');try{let t=await token();if(!t)throw Error('Session expired. Please sign in again.');let item={id:session.user.id,display_name:display.querySelector('input').value.trim().slice(0,40),avatar:selectedAvatar,accent:profile.accent||'rose',updated_at:new Date().toISOString()};await call('/rest/v1/kage_profiles?on_conflict=id',{method:'POST',token:t,body:item,prefer:'resolution=merge-duplicates,return=minimal'});profile={...profile,...item};updateButton();setMessage('Profile saved.')}catch(e){setMessage(e.message)}finally{save.disabled=false}};logout.onclick=async()=>{let t=await token();if(t)try{await call('/auth/v1/logout',{method:'POST',token:t})}catch(e){}saveSession(null);profile={display_name:'',avatar:'photo1',accent:'rose'};applyAccent('rose');activeTab='account';updateButton();draw()}}
function drawSettings(box){let desc=element('p','kg-note','Choose your account accent colour. Your preference syncs across devices.');let wrap=element('label','kg-field','Accent colour'),sel=element('select');[['rose','Rose'],['blue','Blue'],['purple','Purple']].forEach(([v,l])=>{let o=element('option','',l);o.value=v;sel.append(o)});sel.value=profile.accent||'rose';wrap.append(sel);let msg=element('p','kg-message'),save=element('button','kg-primary','Save settings');save.type='button';box.append(desc,wrap,msg,save);save.onclick=async()=>{save.disabled=true;setMessage('Saving...');try{let t=await token();if(!t)throw Error('Session expired. Please sign in again.');let row={id:session.user.id,display_name:profile.display_name||'',avatar:(photoAvatars[profile.avatar]?profile.avatar:'photo1'),accent:sel.value,updated_at:new Date().toISOString()};await call('/rest/v1/kage_profiles?on_conflict=id',{method:'POST',token:t,body:row,prefer:'resolution=merge-duplicates,return=minimal'});profile={...profile,...row};applyAccent(sel.value);setMessage('Settings saved.')}catch(e){setMessage(e.message)}finally{save.disabled=false}}}
async function drawHistory(box){let note=element('p','kg-note','Recently opened episodes on your signed-in devices. Opening a watch page saves it; playback position is not tracked.');let list=element('div'),message=element('p','kg-message','Loading history...');box.append(note,message,list);try{let t=await token();if(!t)throw Error('Session expired. Please sign in again.');let rows=await call('/rest/v1/kage_history?user_id=eq.'+encodeURIComponent(session.user.id)+'&select=title,watch_url,episode,watched_at,content_key&order=watched_at.desc&limit=50',{token:t});message.textContent=rows?.length?'':'No watch history yet.';for(let row of rows||[]){let item=element('div','kg-history-item'),a=element('a','',row.title),small=element('small','',(row.episode?'Episode '+row.episode+' · ':'')+new Date(row.watched_at).toLocaleString());a.href='/watch?'+new URLSearchParams({url:row.watch_url,title:row.title});a.append(small);let remove=element('button','','Remove');remove.type='button';remove.onclick=async()=>{try{let tk=await token();await call('/rest/v1/kage_history?user_id=eq.'+encodeURIComponent(session.user.id)+'&content_key=eq.'+encodeURIComponent(row.content_key),{method:'DELETE',token:tk});item.remove();if(!list.children.length)message.textContent='No watch history yet.'}catch(e){message.textContent=e.message}};item.append(a,remove);list.append(item)}}catch(e){message.textContent=e.message}}
async function record(title,url,episode){try{await ready;if(!config?.configured||!session?.user||!title||!url)return;let t=await token();if(!t)return;let row={user_id:session.user.id,content_key:title.toLowerCase().trim().slice(0,180),title:title.slice(0,180),watch_url:url.slice(0,1500),episode:String(episode||'').slice(0,20),watched_at:new Date().toISOString()};await call('/rest/v1/kage_history?on_conflict=user_id,content_key',{method:'POST',token:t,body:row,prefer:'resolution=merge-duplicates,return=minimal'})}catch(e){console.warn('Watch history could not be saved:',e.message)}}
function mount(){let header=document.querySelector('header');if(!header||document.querySelector('.kg-account-button'))return;let b=element('button','kg-account-button');b.type='button';b.setAttribute('aria-label','Account and watch history');let img=element('img');img.src=avatar('photo1');img.alt='';let label=element('span','','Sign in');b.append(img,label);b.onclick=()=>open('account');header.append(b);updateButton()}
const ready=(async()=>{mount();try{let r=await fetch('/api/auth-config');config=await r.json();if(!config.configured)return;saveSession(loadSession());if(session){if(await token())await fetchProfile();updateButton()}}catch(e){config={configured:false}}})();
try{applyAccent(localStorage.getItem(prefs)||'rose')}catch(e){}window.KageAccount={open,record,ready};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&dialog)close()});
})();
